import { useState, useRef, useCallback, useEffect } from "react";
import { Upload, Download, Sparkles, X, RotateCcw, Layers, Sliders } from "lucide-react";
import { rgbToHex } from "@/utils/color";

const MAX_DIM = 1000;

export default function RgbAdjust() {
  return (
    <div className="container py-10 lg:py-14">
      <header className="mb-8 animate-fade-up">
        <div className="flex items-end justify-between gap-4 flex-wrap">
          <div>
            <div className="inline-flex items-center gap-2 rounded-full bg-blue-50 border border-blue-100 px-3 py-1.5 text-[12px] font-semibold text-blue-600">
              <Layers className="w-3.5 h-3.5" strokeWidth={2.2} />
              RGB 色彩模型 · 通道调节
            </div>
            <h1 className="mt-4 font-display text-4xl lg:text-5xl font-extrabold tracking-tight leading-[1.1] text-slate-900">
              RGB <span className="font-light text-slate-400">色彩空间</span>
            </h1>
          </div>
          <div className="flex flex-wrap items-center gap-2 text-[12.5px] font-medium text-slate-400">
            <span className="inline-flex items-center gap-1.5 rounded-lg bg-white border border-slate-200/70 px-2.5 py-1.5">
              <Layers className="w-3.5 h-3.5 text-blue-500" strokeWidth={2.2} />
              三通道
            </span>
            <span className="inline-flex items-center gap-1.5 rounded-lg bg-white border border-slate-200/70 px-2.5 py-1.5">
              <Sliders className="w-3.5 h-3.5 text-blue-500" strokeWidth={2.2} />
              通道调节
            </span>
          </div>
        </div>
        <p className="mt-5 max-w-3xl text-[15px] leading-relaxed text-slate-500">
          RGB 是显示设备最基础的色彩模型,用 <span className="font-semibold text-slate-700">红(Red)、绿(Green)、蓝(Blue)</span> 三种基色的加法混色,
          组合出约 1670 万种颜色。上传图片后,用右侧拉条调节每个通道的强度,左侧实时预览三通道分离效果。
        </p>
      </header>

      {/* 主工作区:图片在左,拉条在右 */}
      <section className="animate-fade-up delay-1">
        <RgbWorkbench />
      </section>
    </div>
  );
}

/* ---------------- 主工作区 ---------------- */
function RgbWorkbench() {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sourceCanvasRef = useRef<HTMLCanvasElement>(null);
  const sourceDataRef = useRef<ImageData | null>(null);
  const canvasRefs = useRef<Record<"original" | "r" | "g" | "b", HTMLCanvasElement | null>>({
    original: null, r: null, g: null, b: null,
  });

  const [hasImage, setHasImage] = useState(false);
  const [imgSize, setImgSize] = useState<{ w: number; h: number } | null>(null);
  const [rGain, setRGain] = useState(255);
  const [gGain, setGGain] = useState(255);
  const [bGain, setBGain] = useState(255);

  const render = useCallback(() => {
    const data = sourceDataRef.current;
    if (!data) return;
    const adjusted = applyGain(data, rGain, gGain, bGain);
    (["original", "r", "g", "b"] as const).forEach((ch) => {
      const canvas = canvasRefs.current[ch];
      if (!canvas) return;
      canvas.width = data.width;
      canvas.height = data.height;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      if (ch === "original") {
        ctx.putImageData(data, 0, 0);
        return;
      }
      ctx.putImageData(channelGray(adjusted, ch), 0, 0);
    });
  }, [rGain, gGain, bGain]);

  // hasImage 或增益变化时,等待 canvas 挂载后渲染
  useEffect(() => {
    if (!hasImage || !sourceDataRef.current) return;
    const id = requestAnimationFrame(render);
    return () => cancelAnimationFrame(id);
  }, [hasImage, render]);

  const applySrc = useCallback((src: string) => {
    const img = new Image();
    img.onload = () => {
      let w = img.width;
      let h = img.height;
      if (w > MAX_DIM || h > MAX_DIM) {
        const ratio = Math.min(MAX_DIM / w, MAX_DIM / h);
        w = Math.round(w * ratio);
        h = Math.round(h * ratio);
      }
      const source = sourceCanvasRef.current;
      if (!source) return;
      source.width = w;
      source.height = h;
      const ctx = source.getContext("2d", { willReadFrequently: true });
      if (!ctx) return;
      ctx.clearRect(0, 0, w, h);
      ctx.drawImage(img, 0, 0, w, h);
      sourceDataRef.current = ctx.getImageData(0, 0, w, h);

      setImgSize({ w, h });
      setHasImage(true);
    };
    img.onerror = () => console.error("图片加载失败");
    img.src = src;
  }, []);

  const handleFile = useCallback(
    (file: File) => {
      if (!file.type.startsWith("image/")) return;
      applySrc(URL.createObjectURL(file));
    },
    [applySrc]
  );

  const loadSample = useCallback(() => {
    const c = document.createElement("canvas");
    c.width = 800;
    c.height = 400;
    const ctx = c.getContext("2d");
    if (!ctx) return;
    const grad = ctx.createLinearGradient(0, 0, 800, 0);
    grad.addColorStop(0, "#FF0000");
    grad.addColorStop(0.5, "#00FF00");
    grad.addColorStop(1, "#0000FF");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 800, 260);
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.arc(400, 200, 90, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#FFD400";
    ctx.fillRect(0, 320, 800, 80);
    applySrc(c.toDataURL("image/png"));
  }, [applySrc]);

  const handleClear = () => {
    setHasImage(false);
    setImgSize(null);
    setRGain(255);
    setGGain(255);
    setBGain(255);
    sourceDataRef.current = null;
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleReset = () => {
    setRGain(255);
    setGGain(255);
    setBGain(255);
  };

  const handleDownload = (ch: "original" | "r" | "g" | "b") => {
    const canvas = canvasRefs.current[ch];
    if (!canvas) return;
    const link = document.createElement("a");
    link.download = `rgb-${ch}-${Date.now()}.png`;
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const CHANNEL_DEFS: { key: "original" | "r" | "g" | "b"; label: string; color: string }[] = [
    { key: "original", label: "原图", color: "#64748B" },
    { key: "r", label: "R 红通道", color: "#EF4444" },
    { key: "g", label: "G 绿通道", color: "#10B981" },
    { key: "b", label: "B 蓝通道", color: "#3B82F6" },
  ];

  const mixedColor = `rgb(${rGain}, ${gGain}, ${bGain})`;
  const secondaries = [
    { label: "R + G", name: "黄", bg: `rgb(${rGain}, ${gGain}, 0)` },
    { label: "G + B", name: "青", bg: `rgb(0, ${gGain}, ${bGain})` },
    { label: "B + R", name: "品红", bg: `rgb(${rGain}, 0, ${bGain})` },
  ];

  const sectionMark = <span className="h-4 w-1 rounded-full bg-gradient-to-b from-blue-500 to-emerald-400" />;

  return (
    <div className="space-y-6">
      <canvas ref={sourceCanvasRef} className="hidden" />

      {/* 工具栏 */}
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div className="flex items-center gap-2.5 flex-wrap">
          <button
            onClick={() => fileInputRef.current?.click()}
            className="inline-flex items-center gap-2 px-4 py-2.5 bg-blue-500 text-white text-[13.5px] font-semibold rounded-xl shadow-sm shadow-blue-500/25 transition-all hover:bg-blue-600 hover:shadow-md hover:shadow-blue-500/25 active:scale-[0.98]"
          >
            <Upload className="w-4 h-4" strokeWidth={2.2} />
            {hasImage ? "更换图片" : "上传图片"}
          </button>
          <button
            onClick={loadSample}
            className="inline-flex items-center gap-1.5 px-3.5 py-2.5 border border-emerald-200 bg-emerald-50 text-emerald-600 text-[13.5px] font-semibold rounded-xl transition-colors hover:border-emerald-300 hover:bg-emerald-100"
          >
            <Sparkles className="w-4 h-4" strokeWidth={2.2} />
            示例图
          </button>
          {hasImage && (
            <button
              onClick={handleClear}
              className="inline-flex items-center gap-1.5 px-3.5 py-2.5 border border-slate-200 bg-white text-slate-500 text-[13.5px] font-semibold rounded-xl transition-colors hover:border-slate-300 hover:bg-slate-50 hover:text-slate-700"
            >
              <X className="w-4 h-4" strokeWidth={2.2} />
              清除
            </button>
          )}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => {
              const f = e.target.files?.[0];
              if (f) handleFile(f);
            }}
          />
        </div>
        {hasImage && (
          <span className="inline-flex items-center gap-2 rounded-lg bg-slate-100 px-3 py-1.5 font-mono text-[12.5px] tabular-nums text-slate-500">
            {imgSize?.w} × {imgSize?.h}px
          </span>
        )}
      </div>

      {!hasImage ? (
        <div
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault();
            const f = e.dataTransfer.files?.[0];
            if (f) handleFile(f);
          }}
          className="aspect-[16/8] border-2 border-dashed border-slate-300/90 rounded-3xl grid place-items-center bg-white/70 transition-colors hover:border-blue-400"
        >
          <div className="text-center px-6">
            <button onClick={() => fileInputRef.current?.click()} className="group inline-flex flex-col items-center">
              <div className="inline-flex w-16 h-16 items-center justify-center rounded-2xl bg-gradient-to-br from-blue-500 to-emerald-400 text-white mb-5 shadow-lg shadow-blue-500/25 group-hover:scale-105 transition-transform">
                <Upload className="w-7 h-7" strokeWidth={2.2} />
              </div>
              <div className="text-xl font-bold tracking-tight text-slate-800">点击上传</div>
              <div className="text-[14.5px] text-slate-400 mt-1">或拖拽图片到这里</div>
            </button>
            <button
              onClick={loadSample}
              className="mt-6 inline-flex items-center gap-1.5 px-5 py-2.5 border border-emerald-200 bg-emerald-50 text-emerald-600 text-[13.5px] font-semibold rounded-xl transition-colors hover:border-emerald-300 hover:bg-emerald-100"
            >
              <Sparkles className="w-4 h-4" strokeWidth={2.2} />
              加载示例图
            </button>
            <div className="mt-5 text-[12.5px] text-slate-400 font-mono">
              JPG · PNG · WEBP · 本地处理,不上传服务器
            </div>
          </div>
        </div>
      ) : (
        <div className="grid lg:grid-cols-[minmax(0,1fr)_340px] gap-6 items-start">
          {/* 左:图片(4 视图 2×2) */}
          <div className="min-w-0 grid grid-cols-2 gap-4">
            {CHANNEL_DEFS.map((ch) => (
              <div key={ch.key} className="group relative rounded-2xl border bg-white overflow-hidden border-slate-200/80 shadow-soft">
                <canvas
                  ref={(el) => { canvasRefs.current[ch.key] = el; }}
                  className="block w-full h-auto bg-slate-50"
                />
                <div className="absolute top-2.5 left-2.5 inline-flex items-center gap-1.5 rounded-lg border border-slate-200/60 bg-white/90 px-2 py-1 shadow-sm backdrop-blur">
                  <span className="h-1.5 w-1.5 rounded-full" style={{ background: ch.color }} />
                  <span className="text-[12px] font-semibold text-slate-700">{ch.label}</span>
                </div>
                <button
                  onClick={() => handleDownload(ch.key)}
                  className="absolute top-2.5 right-2.5 grid h-7 w-7 place-items-center rounded-lg border border-slate-200/60 bg-white/90 text-slate-500 shadow-sm backdrop-blur transition-colors hover:border-blue-200 hover:bg-blue-50 hover:text-blue-600"
                  title={`下载 ${ch.label}`}
                >
                  <Download className="w-3.5 h-3.5" strokeWidth={2.2} />
                </button>
              </div>
            ))}
          </div>

          {/* 右:调节面板 */}
          <aside className="space-y-5">
            <div className="p-5 bg-white border border-slate-200/80 rounded-2xl shadow-soft">
              <div className="flex items-center justify-between mb-5">
                <div className="text-[13px] font-semibold text-slate-500 flex items-center gap-2.5">
                  {sectionMark}
                  <Sliders className="w-4 h-4 text-blue-500" strokeWidth={2.2} />
                  通道强度 · 实时预览
                </div>
                <button
                  onClick={handleReset}
                  className="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-[12.5px] font-medium text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
                >
                  <RotateCcw className="w-3.5 h-3.5" strokeWidth={2.2} />
                  重置
                </button>
              </div>

              <div className="space-y-5">
                <ChannelSlider label="红 Red" color="#EF4444" value={rGain} onChange={setRGain} />
                <ChannelSlider label="绿 Green" color="#10B981" value={gGain} onChange={setGGain} />
                <ChannelSlider label="蓝 Blue" color="#3B82F6" value={bGain} onChange={setBGain} />
              </div>

              <p className="mt-5 pt-4 border-t border-slate-100 text-[12.5px] text-slate-400 leading-relaxed">
                每个通道 0–255,255 为原始强度。调低某个通道会衰减该颜色的亮度,拉满三通道得到原始图像。
              </p>
            </div>

            {/* 合成色预览 */}
            <div className="p-5 bg-white border border-slate-200/80 rounded-2xl shadow-soft">
              <div className="text-[13px] font-semibold text-slate-500 mb-4 flex items-center gap-2.5">
                {sectionMark}
                合成预览
              </div>
              <div className="h-20 rounded-2xl border border-slate-200/60 shadow-sm transition-colors" style={{ background: mixedColor }} />
              <div className="mt-3 flex items-center justify-between">
                <span className="font-mono text-[13px] text-slate-500">rgb({rGain}, {gGain}, {bGain})</span>
                <span className="font-mono text-[14px] font-bold text-slate-900">{rgbToHex(rGain, gGain, bGain)}</span>
              </div>
              <div className="mt-4 border-t border-slate-100 pt-4 grid grid-cols-3 gap-2">
                {secondaries.map((s) => (
                  <div key={s.label} className="text-center">
                    <div className="h-10 rounded-lg border border-slate-200/60 shadow-sm transition-colors" style={{ background: s.bg }} />
                    <div className="mt-1.5 font-mono text-[11px] text-slate-400">{s.label}</div>
                    <div className="text-[11px] text-slate-400">{s.name}</div>
                  </div>
                ))}
              </div>
            </div>
          </aside>
        </div>
      )}
    </div>
  );
}

function ChannelSlider({ label, color, value, onChange }: { label: string; color: string; value: number; onChange: (v: number) => void }) {
  const pct = (value / 255) * 100;
  return (
    <div>
      <div className="flex items-baseline justify-between mb-2.5">
        <span className="text-[13.5px] font-medium text-slate-500">{label}</span>
        <span className="rounded-md bg-slate-100 px-2 py-0.5 font-mono text-[12.5px] font-semibold tabular-nums text-slate-700">
          {value}
        </span>
      </div>
      <input
        type="range"
        min={0}
        max={255}
        step={1}
        value={value}
        onChange={(e) => onChange(parseInt(e.target.value, 10))}
        className="ana-slider"
        style={{
          background: `linear-gradient(90deg, ${color} 0%, ${color} ${pct}%, #E8EDF3 ${pct}%, #E8EDF3 100%)`,
        }}
      />
    </div>
  );
}

/* ---------------- 通道增益 / 单通道灰度 ---------------- */
function applyGain(data: ImageData, r: number, g: number, b: number): ImageData {
  const out = new ImageData(data.width, data.height);
  const s = data.data;
  const d = out.data;
  for (let i = 0; i < s.length; i += 4) {
    d[i] = Math.round((s[i] * r) / 255);
    d[i + 1] = Math.round((s[i + 1] * g) / 255);
    d[i + 2] = Math.round((s[i + 2] * b) / 255);
    d[i + 3] = s[i + 3];
  }
  return out;
}

function channelGray(data: ImageData, ch: "r" | "g" | "b"): ImageData {
  const out = new ImageData(data.width, data.height);
  const s = data.data;
  const d = out.data;
  for (let i = 0; i < s.length; i += 4) {
    const v = ch === "r" ? s[i] : ch === "g" ? s[i + 1] : s[i + 2];
    d[i] = v;
    d[i + 1] = v;
    d[i + 2] = v;
    d[i + 3] = 255;
  }
  return out;
}